//! SSX 3 (USA) — native recompilation, windowed front end.
//!
//! Boots the recompiled EE code (`ssx3-ee`, generated by `recomp-ee`) on the
//! `ssx3-ps2` platform layer and presents GS output with `wgpu`.
//!
//! Keys (pad 1): arrows = d-pad, X = Cross, Z = Square, S = Circle, A = Triangle,
//! Enter = Start, Right Shift = Select, Q/W = L1/R1, 1/2 = L2/R2.
//! Game controllers (via gilrs) map to pad 1 too, analog sticks included; a
//! second controller drives pad 2 when `SSX3_PAD2=1` plugs it in (Multi Play).

// The generated EE code in the chosen form (features `ee-threads` / `ee-unwind`).
#[cfg(feature = "ee-unwind")]
extern crate ssx3_ee_unwind as ssx3_ee;
#[cfg(all(feature = "ee-threads", not(feature = "ee-unwind")))]
extern crate ssx3_ee_threads as ssx3_ee;

use std::sync::Arc;
use std::time::{Duration, Instant};

use winit::application::ApplicationHandler;
use winit::event::{ElementState, WindowEvent};
use winit::event_loop::{ActiveEventLoop, ControlFlow, EventLoop};
use winit::keyboard::{KeyCode, PhysicalKey};
use winit::window::{Fullscreen, Window, WindowId};

mod game;
mod png;
mod present;
mod settings;

use present::Presenter;
use ssx3_ps2::Cpu;

struct App {
    cpu: Box<Cpu>,
    window: Option<Arc<Window>>,
    presenter: Option<Presenter>,
    frame: Vec<u32>,
    last: Instant,
    started: Instant,
    exit_after: Option<u64>,
    shots: u64,
    fps_mark: Instant,
    /// Pad 1 buttons held on the keyboard / on a game controller (libpad bits).
    keys: u16,
    gilrs: Option<gilrs::Gilrs>,
    /// Ticket of the previous frame's display request (MTGS): the window
    /// shows frame N-1 (or newer) while the GS thread finishes frame N.
    pending_display: Option<u64>,
    /// The GS's wgpu device (GPU backend).
    gpu_ctx: Option<&'static ssx3_ps2::gpu::GpuContext>,
    /// The draw-layer renderer (`SSX3_RENDER`, native by default).
    gfx: Option<ssx3_gfx::Renderer>,
    /// The frame pacer: the game runs on the wall clock at the game rate,
    /// whatever the display or the host does.
    pacer: ssx3_game::tick::Pacer,
    /// `SSX3_CATCHUP` (on by default): extra updates per VSync when the host
    /// is too slow for the game rate.
    catch_up: bool,
    /// The display's refresh rate (Hz).
    display_hz: f64,
    /// The settings overlay (F10): open with this row selected; the game
    /// is paused meanwhile.
    menu: Option<usize>,
    /// A setting that applies after a restart was changed.
    restart_pending: bool,
    /// Game frames to run while the overlay is open: after a change that
    /// applies at once, so the image behind shows it.
    preview: u32,
}

/// Settings that are renderer options (`game::gfx_options`).
const GFX_KEYS: &[&str] = &[
    "SSX3_AA",
    "SSX3_MIPMAPS",
    "SSX3_LOD_BIAS",
    "SSX3_TERRAIN",
    "SSX3_AO",
    "SSX3_BLOOM",
    "SSX3_SNOW",
];

/// The game's field time: one tick at the game rate (59.94 Hz originally,
/// `SSX3_TICK_HZ`).
fn field() -> Duration {
    match ssx3_ps2::machine::vsync_hz() {
        60 => Duration::from_micros(16_683),
        hz => Duration::from_secs_f64(1.001 / hz as f64),
    }
}

/// libpad button bit for a controller button.
fn gamepad_bit(b: gilrs::Button) -> Option<u16> {
    use gilrs::Button::*;
    Some(match b {
        Select => 1 << 0,
        LeftThumb => 1 << 1,
        RightThumb => 1 << 2,
        Start => 1 << 3,
        DPadUp => 1 << 4,
        DPadRight => 1 << 5,
        DPadDown => 1 << 6,
        DPadLeft => 1 << 7,
        LeftTrigger2 => 1 << 8,
        RightTrigger2 => 1 << 9,
        LeftTrigger => 1 << 10,
        RightTrigger => 1 << 11,
        North => 1 << 12,
        East => 1 << 13,
        South => 1 << 14,
        West => 1 << 15,
        _ => return None,
    })
}

impl App {
    /// Merge keyboard and controller state into the pads: the keyboard and
    /// the first game controller drive pad 1, a second controller pad 2
    /// (plugged in with `SSX3_PAD2=1`).
    fn update_pad(&mut self) {
        let mut state = [(self.keys, [0x80u8; 4]), (0u16, [0x80u8; 4])];
        let mut open_menu = false;
        if let Some(g) = self.gilrs.as_mut() {
            while let Some(ev) = g.next_event() {
                match ev.event {
                    gilrs::EventType::Connected => {
                        let p = g.gamepad(ev.id);
                        eprintln!(
                            "[pad] controller connected: {} (vendor {:04x?}, product {:04x?}, mapping {:?})",
                            p.name(),
                            p.vendor_id(),
                            p.product_id(),
                            p.mapping_source()
                        );
                    }
                    gilrs::EventType::ButtonPressed(b, code) if std::env::var_os("SSX3_PAD_DEBUG").is_some() => {
                        eprintln!("[pad] pressed {b:?} (code {code:?})");
                    }
                    gilrs::EventType::AxisChanged(a, v, code) if std::env::var_os("SSX3_PAD_DEBUG").is_some() && v.abs() > 0.5 => {
                        eprintln!("[pad] axis {a:?} {v:.2} (code {code:?})");
                    }
                    gilrs::EventType::Disconnected => eprintln!("[pad] controller disconnected: {}", g.gamepad(ev.id).name()),
                    // The controller's home/guide button opens the settings.
                    gilrs::EventType::ButtonPressed(gilrs::Button::Mode, _) => open_menu = true,
                    _ => {}
                }
            }
            for (port, (_, pad)) in g.gamepads().take(2).enumerate() {
                let (buttons, sticks) = &mut state[port];
                for b in [
                    gilrs::Button::Select, gilrs::Button::LeftThumb, gilrs::Button::RightThumb,
                    gilrs::Button::Start, gilrs::Button::DPadUp, gilrs::Button::DPadRight,
                    gilrs::Button::DPadDown, gilrs::Button::DPadLeft, gilrs::Button::LeftTrigger2,
                    gilrs::Button::RightTrigger2, gilrs::Button::LeftTrigger, gilrs::Button::RightTrigger,
                    gilrs::Button::North, gilrs::Button::East, gilrs::Button::South, gilrs::Button::West,
                ] {
                    if let Some(bit) = gamepad_bit(b) {
                        if pad.is_pressed(b) {
                            *buttons |= bit;
                        }
                    }
                }
                // PS2 sticks: 0 = left/up, 0xFF = right/down; gilrs Y is up-positive.
                let axis = |a: gilrs::Axis, flip: bool| {
                    let v = pad.value(a);
                    let v = if flip { -v } else { v };
                    ((v.clamp(-1.0, 1.0) * 127.5) + 127.5).round() as u8
                };
                *sticks = [
                    axis(gilrs::Axis::RightStickX, false),
                    axis(gilrs::Axis::RightStickY, true),
                    axis(gilrs::Axis::LeftStickX, false),
                    axis(gilrs::Axis::LeftStickY, true),
                ];
            }
        }
        if open_menu && self.menu.is_none() {
            self.toggle_menu();
        }
        let sif = &mut ssx3_ps2::m!(self.cpu).sif;
        for (port, (buttons, sticks)) in state.into_iter().enumerate() {
            sif.pad_buttons[port] = buttons;
            sif.pad_sticks[port] = sticks;
        }
    }
}

fn pad_bit(k: KeyCode) -> Option<u16> {
    // libpad button bits (active-low in the wire format; we store active-high).
    Some(match k {
        KeyCode::ShiftRight => 1 << 0,  // Select
        KeyCode::Enter => 1 << 3,       // Start
        KeyCode::ArrowUp => 1 << 4,
        KeyCode::ArrowRight => 1 << 5,
        KeyCode::ArrowDown => 1 << 6,
        KeyCode::ArrowLeft => 1 << 7,
        KeyCode::Digit1 => 1 << 8,      // L2
        KeyCode::Digit2 => 1 << 9,      // R2
        KeyCode::KeyQ => 1 << 10,       // L1
        KeyCode::KeyW => 1 << 11,       // R1
        KeyCode::KeyA => 1 << 12,       // Triangle
        KeyCode::KeyS => 1 << 13,       // Circle
        KeyCode::KeyX => 1 << 14,       // Cross
        KeyCode::KeyZ => 1 << 15,       // Square
        _ => return None,
    })
}

impl ApplicationHandler for App {
    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
        if self.window.is_some() {
            return;
        }
        let attrs = Window::default_attributes()
            .with_title("SSX 3 (USA) — native recompilation")
            .with_inner_size(winit::dpi::LogicalSize::new(960.0, 672.0));
        // SSX3_FULLSCREEN=1: start in borderless fullscreen (F11 toggles).
        let attrs = if settings::get("SSX3_FULLSCREEN").is_some_and(|v| v != "0") { attrs.with_fullscreen(Some(Fullscreen::Borderless(None))) } else { attrs };
        let window = Arc::new(event_loop.create_window(attrs).expect("window"));
        let gs = ssx3_ps2::gpu::context();
        self.gpu_ctx = gs;
        self.presenter = Some(pollster::block_on(Presenter::new(window.clone(), gs)));
        let size = window.inner_size();
        self.display_hz = window
            .current_monitor()
            .and_then(|m| m.refresh_rate_millihertz())
            .map_or(60.0, |m| (m as f64 / 1000.0).clamp(24.0, 500.0));
        let game_hz = ssx3_ps2::machine::vsync_hz() as f64 / 1.001;
        let locked = self.pacer.lock_to_display(game_hz, self.display_hz);
        eprintln!(
            "[window] display {:.0} Hz, game {} Hz{}",
            self.display_hz,
            ssx3_ps2::machine::vsync_hz(),
            if locked { ", locked to the display" } else { "" }
        );
        self.window = Some(window);
        self.follow_window_size(size.width, size.height);
    }

    fn window_event(&mut self, event_loop: &ActiveEventLoop, _id: WindowId, event: WindowEvent) {
        match event {
            WindowEvent::CloseRequested => event_loop.exit(),
            WindowEvent::Resized(size) => {
                if let Some(p) = self.presenter.as_mut() {
                    p.resize(size.width, size.height);
                }
                self.follow_window_size(size.width, size.height);
            }
            WindowEvent::KeyboardInput { event, .. } => {
                if let PhysicalKey::Code(code) = event.physical_key {
                    let pressed = event.state == ElementState::Pressed;
                    if code == KeyCode::F10 && pressed && !event.repeat {
                        self.toggle_menu();
                        return;
                    }
                    if self.menu.is_some() {
                        if pressed {
                            match code {
                                KeyCode::ArrowUp => self.menu_input(MenuKey::Up),
                                KeyCode::ArrowDown => self.menu_input(MenuKey::Down),
                                KeyCode::ArrowLeft => self.menu_input(MenuKey::Left),
                                KeyCode::ArrowRight => self.menu_input(MenuKey::Right),
                                KeyCode::Enter | KeyCode::Space | KeyCode::KeyX => self.menu_input(MenuKey::Select),
                                KeyCode::Escape | KeyCode::Backspace => self.menu_input(MenuKey::Close),
                                _ => {}
                            }
                        }
                        return;
                    }
                    // F11: borderless fullscreen on and off.
                    if code == KeyCode::F11 && event.state == ElementState::Pressed && !event.repeat {
                        if let Some(w) = self.window.as_ref() {
                            w.set_fullscreen(if w.fullscreen().is_some() { None } else { Some(Fullscreen::Borderless(None)) });
                        }
                    }
                    if code == KeyCode::F12 && event.state == ElementState::Pressed {
                        // The image on screen: the native renderer's while it is active.
                        let native = self.gfx.as_ref().filter(|_| ssx3_ps2::frame_sink::native()).and_then(|g| g.read_image());
                        let (w, h) = match native {
                            Some((w, h, px)) => {
                                self.frame = px.iter().map(|p| p | 0xFF00_0000).collect();
                                (w, h)
                            }
                            #[cfg(feature = "emu-gs")]
                            None => ssx3_ps2::m!(self.cpu).hw.gs.core().display(&mut self.frame),
                            #[cfg(not(feature = "emu-gs"))]
                            None => (0, 0),
                        };
                        let path = format!("/tmp/ssx3-shot-{}.png", self.shots);
                        self.shots += 1;
                        let _ = std::fs::write(&path, png::encode(w, h, &self.frame));
                        eprintln!("screenshot: {path}");
                    }
                    if let Some(bit) = pad_bit(code) {
                        if event.state == ElementState::Pressed {
                            self.keys |= bit;
                        } else {
                            self.keys &= !bit;
                        }
                    }
                }
            }
            WindowEvent::RedrawRequested => {
                // The settings overlay pauses the game.
                if self.menu.is_some() {
                    self.poll_menu_pad();
                    // (Paused: the pacer starts over when the game resumes.)
                    self.pacer.reset();
                    ssx3_game::tick::set_updates_per_vsync(1);
                    if self.preview > 0 {
                        self.preview -= 1;
                        if !self.step(event_loop) {
                            return;
                        }
                    }
                    self.show();
                    return;
                }
                // Fixed-timestep loop: the VSyncs (game updates) the wall
                // clock asks for, then the newest image. A display slower
                // than the game rate gets several VSyncs per image, a faster
                // one waits for the next update.
                let period = field().as_secs_f64();
                let now = self.started.elapsed().as_secs_f64();
                let game_hz = ssx3_ps2::machine::vsync_hz() as f64 / 1.001;
                let max_vsyncs = (game_hz / self.display_hz - 0.01).ceil().max(1.0) as u32;
                let plan = self.pacer.plan(now, period, max_vsyncs, self.catch_up);
                if plan.vsyncs == 0 {
                    if self.pacer.repeat_image() {
                        // Show the last image again: the next call comes
                        // with the next display refresh.
                        self.show();
                        return;
                    }
                    let w = self.pacer.wait(now, period);
                    std::thread::sleep(Duration::from_secs_f64(w.min(0.002)));
                    return;
                }
                ssx3_ps2::machine::set_audio_lead_frames((self.pacer.audio_lead() * 48000.0) as u32);
                ssx3_game::tick::set_updates_per_vsync(plan.updates_per_vsync);
                for _ in 0..plan.vsyncs {
                    if !self.step(event_loop) {
                        return;
                    }
                }
                self.show();
            }
            _ => {}
        }
    }

    fn about_to_wait(&mut self, _event_loop: &ActiveEventLoop) {
        if let Some(w) = self.window.as_ref() {
            w.request_redraw();
        }
    }
}

impl App {
    /// Run one game frame; false when the game halted.
    fn step(&mut self, event_loop: &ActiveEventLoop) -> bool {
        self.update_pad();
        let alive = ssx3_ps2::machine::run_frame(&mut self.cpu);
        if ssx3_ps2::m!(self.cpu).sched.frames % 60 == 0 {
            eprintln!("[{:6.1}s] {}", self.started.elapsed().as_secs_f64(), game::status(&self.cpu));
            {
                let app = self.cpu.bus.read32(ssx3_game::tick::APPMAN_PTR);
                let updates = if app != 0 { self.cpu.bus.read32(app + 0x1c) } else { 0 };
                eprintln!(
                    "          game updates {updates}, audio gaps {:.2}s total, lead {} ms, repeated images {}, catch-up VSyncs {}",
                    ssx3_iop::audio::underrun_frames() as f64 / 48000.0,
                    ssx3_ps2::machine::audio_lead_frames() / 48,
                    self.pacer.repeats,
                    self.pacer.doubled
                );
            }
            let now = Instant::now();
            let fps = 60.0 / now.duration_since(self.fps_mark).as_secs_f64().max(1e-6);
            self.fps_mark = now;
            if let Some(w) = self.window.as_ref() {
                w.set_title(&format!("SSX 3 (USA) — native recompilation — {fps:.0} fps"));
            }
        }
        if !alive {
            eprintln!("halted: {:?}", ssx3_ps2::m!(self.cpu).kernel.halted);
            event_loop.exit();
            return false;
        }
        if let Some(n) = self.exit_after {
            if ssx3_ps2::m!(self.cpu).sched.frames >= n {
                event_loop.exit();
            }
        }
        true
    }

    /// Present the latest image.
    fn show(&mut self) {
        if let Some(p) = self.presenter.as_mut() {
            // Rendering at the window's size fills it exactly.
            let native_fill = self.gfx.is_some() && ssx3_ps2::frame_sink::native() && game::follows_window();
            p.set_aspect(if native_fill { game::aspect_box().unwrap_or(0.0) } else { display_aspect(&self.cpu) });
            match self.menu {
                Some(sel) => {
                    let (w, h, img) = settings::draw(sel, self.restart_pending);
                    p.set_overlay(Some((w, h, &img)));
                }
                None => p.set_overlay(None),
            }
        }
        #[cfg(feature = "emu-gs")]
        let gs = &mut ssx3_ps2::m!(self.cpu).hw.gs;
        let native = ssx3_ps2::frame_sink::native();
        match self.presenter.as_mut() {
            // Native: the renderer's latest image (it lives on the
            // GS device: no copy).
            Some(p) if native && self.gfx.is_some() => {
                let g = self.gfx.as_ref().unwrap();
                if p.same_device(self.gpu_ctx) {
                    if let Some((view, _, _)) = g.present_view() {
                        let _ = p.render_view(&view);
                    }
                } else if let Some((w, h, px)) = g.read_image() {
                    self.frame = px.iter().map(|p| p | 0xFF00_0000).collect();
                    let _ = p.render(w, h, &self.frame);
                }
            }
            // GPU GS: the frame stays on the GPU. The display pass
            // is queued on the GS thread right behind this frame's
            // drawing; the previous request's frame (or a newer
            // one) is presented, so the guest never waits for the
            // GS thread to finish the frame it just produced.
            #[cfg(feature = "emu-gs")]
            Some(p) if p.same_device(self.gpu_ctx) => {
                let ticket = gs.request_display();
                let prev = self.pending_display.replace(ticket).unwrap_or(ticket);
                match gs.take_display(prev) {
                    Some(Some(frame)) => {
                        let _ = p.render_gpu(&frame);
                    }
                    Some(None) => {
                        let (w, h) = gs.core().display(&mut self.frame);
                        let _ = p.render(w, h, &self.frame);
                    }
                    None => {} // nothing new: keep the last image
                }
            }
            #[cfg(feature = "emu-gs")]
            Some(p) => {
                let (w, h) = gs.core().display(&mut self.frame);
                let _ = p.render(w, h, &self.frame);
            }
            _ => {}
        }
        self.last = Instant::now();
    }

    /// Native window: render at the window's pixel size, the game's view
    /// widened to its aspect (and `SSX3_FOV`).
    fn follow_window_size(&mut self, w: u32, h: u32) {
        if w == 0 || h == 0 || !game::follows_window() || !ssx3_ps2::frame_sink::native() {
            return;
        }
        if let Some(g) = self.gfx.as_ref() {
            // The aspect box (SSX3_ASPECT) inside the window, at the chosen
            // resolution.
            let (bw, bh) = match game::aspect_box() {
                Some(a) if w as f32 / h as f32 > a => ((h as f32 * a).round() as u32, h),
                Some(a) => (w, (w as f32 / a).round() as u32),
                None => (w, h),
            };
            let k = game::resolution();
            g.set_output_size(Some((((bw as f32 * k).round() as u32).max(64), ((bh as f32 * k).round() as u32).max(64))));
            ssx3_ps2::frame_sink::set_view(bw as f32 / bh as f32, game::fov());
        }
    }

    /// `SSX3_CATCHUP` (default on): game time and audio follow the wall
    /// clock when the host is slower than the game rate.
    fn apply_catch_up(&mut self) {
        let on = settings::get("SSX3_CATCHUP").is_none_or(|v| v != "0");
        self.catch_up = on;
        self.pacer.reset();
        ssx3_game::tick::set_updates_per_vsync(1);
        ssx3_ps2::machine::set_realtime(on);
    }

    fn toggle_menu(&mut self) {
        self.menu = match self.menu {
            Some(_) => None,
            None => {
                // (No key stays held in the game.)
                self.keys = 0;
                Some(0)
            }
        };
    }

    fn menu_input(&mut self, k: MenuKey) {
        let Some(sel) = self.menu else { return };
        let n = settings::ITEMS.len();
        match k {
            MenuKey::Up => self.menu = Some((sel + n) % (n + 1)),
            MenuKey::Down => self.menu = Some((sel + 1) % (n + 1)),
            MenuKey::Close => self.menu = None,
            MenuKey::Select if sel == n => self.menu = None,
            MenuKey::Left | MenuKey::Right | MenuKey::Select if sel < n => {
                let item = &settings::ITEMS[sel];
                settings::step(item, if k == MenuKey::Left { -1 } else { 1 });
                if item.live {
                    self.apply_setting(item.key);
                    self.preview = 3;
                } else {
                    self.restart_pending = true;
                }
            }
            _ => {}
        }
    }

    /// Apply a changed setting now.
    fn apply_setting(&mut self, key: &str) {
        match key {
            "SSX3_CATCHUP" => self.apply_catch_up(),
            "SSX3_DRAW_DIST" => ssx3_game::detail::set(game::detail_distance()),
            "SSX3_ANISO" => {
                if let Some(g) = self.gfx.as_ref() {
                    g.set_anisotropy(game::anisotropy());
                }
            }
            k if k.starts_with("SSX3_") && GFX_KEYS.contains(&k) => {
                if let Some(g) = self.gfx.as_ref() {
                    g.set_options(game::gfx_options());
                }
            }
            "SSX3_FULLSCREEN" => {
                if let Some(w) = self.window.as_ref() {
                    let on = settings::get("SSX3_FULLSCREEN").is_some_and(|v| v != "0");
                    w.set_fullscreen(on.then_some(Fullscreen::Borderless(None)));
                }
            }
            _ => {
                if let Some(size) = self.window.as_ref().map(|w| w.inner_size()) {
                    self.follow_window_size(size.width, size.height);
                }
            }
        }
    }

    /// Controller navigation while the overlay is open.
    fn poll_menu_pad(&mut self) {
        let mut keys = Vec::new();
        if let Some(g) = self.gilrs.as_mut() {
            while let Some(ev) = g.next_event() {
                if let gilrs::EventType::ButtonPressed(b, _) = ev.event {
                    keys.push(match b {
                        gilrs::Button::DPadUp => MenuKey::Up,
                        gilrs::Button::DPadDown => MenuKey::Down,
                        gilrs::Button::DPadLeft => MenuKey::Left,
                        gilrs::Button::DPadRight => MenuKey::Right,
                        gilrs::Button::South => MenuKey::Select,
                        gilrs::Button::East | gilrs::Button::Mode | gilrs::Button::Start => MenuKey::Close,
                        _ => continue,
                    });
                }
            }
        }
        for k in keys {
            self.menu_input(k);
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum MenuKey {
    Up,
    Down,
    Left,
    Right,
    Select,
    Close,
}

/// The aspect ratio to show the game at. SSX3_ASPECT=4:3 / 16:9 / stretch
/// overrides; by default it follows the game's own widescreen option
/// (options word at 0x535610, bits 20-21: off, 16:9 letterboxed in a 4:3
/// image, anamorphic), so anamorphic is shown at 16:9.
fn display_aspect(cpu: &Cpu) -> f32 {
    static FORCED: std::sync::OnceLock<Option<f32>> = std::sync::OnceLock::new();
    let forced = *FORCED.get_or_init(|| match std::env::var("SSX3_ASPECT").ok()?.as_str() {
        "stretch" => Some(0.0),
        "16:9" => Some(16.0 / 9.0),
        "4:3" => Some(4.0 / 3.0),
        v => {
            eprintln!("SSX3_ASPECT={v}: expected 4:3, 16:9 or stretch");
            None
        }
    });
    forced.unwrap_or(if (cpu.bus.ram_u32(0x0053_5610) >> 20) & 3 == 2 { 16.0 / 9.0 } else { 4.0 / 3.0 })
}

fn main() {
    // A standalone build finds its data first (it chooses the settings file).
    game::init_standalone();
    // Then: the settings file fills in the environment.
    settings::load();
    env_logger::init();
    let mut cpu = game::boot(false);
    let gfx = game::install_renderer(&mut cpu);
    let event_loop = EventLoop::new().expect("event loop");
    event_loop.set_control_flow(ControlFlow::Poll);
    let mut app = App {
        cpu,
        window: None,
        presenter: None,
        gfx,
        frame: Vec::new(),
        last: Instant::now(),
        started: Instant::now(),
        exit_after: std::env::var("SSX3_EXIT_AFTER_FRAMES").ok().and_then(|s| s.parse().ok()),
        shots: 0,
        fps_mark: Instant::now(),
        keys: 0,
        pending_display: None,
        gpu_ctx: None,
        pacer: ssx3_game::tick::Pacer::default(),
        catch_up: true,
        display_hz: 60.0,
        menu: None,
        restart_pending: false,
        preview: 0,
        gilrs: gilrs::Gilrs::new()
            .map(|g| {
                let pads: Vec<String> = g.gamepads().map(|(_, p)| p.name().to_string()).collect();
                // Controllers usually arrive a moment later, as Connected
                // events (logged in `update_pad`).
                if !pads.is_empty() {
                    eprintln!("[pad] controllers: {}", pads.join(", "));
                }
                g
            })
            .map_err(|e| eprintln!("no game controller support: {e}"))
            .ok(),
    };
    app.apply_catch_up();
    if let Err(e) = event_loop.run_app(&mut app) {
        eprintln!("event loop error: {e}");
        std::process::exit(1);
    }
}
